import java.util.Scanner;

public class Main {
    static long[] pattern = new long[20];
    static long[] base_pow = new long[20];
    static int min_step = -1;

    static void setup() {
        base_pow[0] = 1;
        for (int i = 1; i <= 17; ++i)
            base_pow[i] = base_pow[i - 1] * 10;

        pattern[0] = 0;
        for (int i = 1; i <= 17; ++i)
            pattern[i] = pattern[i - 1] * 10 + 1;
    }

    static int get_digits(long num) {
        int count = 0;
        do {
            ++count;
            num /= 10;
        } while (num != 0);
        return count;
    }

    static void dfs(int digit, long val, int steps) {
        if (min_step != -1 && steps >= min_step)
            return;
        if (val == 0 || digit == 0) {
            if (min_step == -1 || steps < min_step)
                min_step = steps;
            return;
        }
        if (val < 0)
            val = -val;

        long temp_val = val;
        int temp_steps = 0;
        while (temp_val >= base_pow[digit - 1]) {
            temp_val -= pattern[digit];
            temp_steps += digit;
        }
        dfs(digit - 1, temp_val, steps + temp_steps);

        temp_val = pattern[digit + 1] - val;
        temp_steps = 0;
        while (temp_val >= base_pow[digit - 1]) {
            temp_val -= pattern[digit];
            temp_steps += digit;
        }
        dfs(digit - 1, temp_val, steps + digit + 1 + temp_steps);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        setup();

        long num = sc.nextLong();
        min_step = -1;
        dfs(get_digits(num), num, 0);
        System.out.println(min_step);
        sc.close();
    }
}
